#[doc = "A line, or a twist or forque: the bivectors. `e23, e31, e12` hold the direction (the Euclidean part), `e01, e02, e03` the moment. As a versor it is a half turn."]
///
/// Blades, in coefficient order: `[e23, e31, e12, e01, e02, e03]`.
///
/// `S` lists the open slots: `Line` (that is, `Line<()>`) is a value, `Line<(A,)>` a
/// linear map from `A`, `Line<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Line<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 6],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Line<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Line<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Line<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Line<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Line");
        for (b, c) in <Line as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Line {
    const N: usize = 6;
    const NAME: &'static str = "Line";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e23", "e31", "e12", "e01", "e02", "e03"];
    type Arr<X: gx::Elem> = [X; 6];
    type Mv<S: gx::Slots, T: gx::Coef> = Line<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 6] {
        [f(0), f(1), f(2), f(3), f(4), f(5)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 6], mut f: impl FnMut(&X) -> Y) -> [Y; 6] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 6],
        b: &[Y; 6],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 6] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5])]
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Extensor for Line<S, T> {
    type Kind = Line;
    type Slots = S;
    type Coef = T;
    #[inline(always)]
    fn from_coeffs(c: [S::Arr<T>; 6]) -> Self {
        Line { c }
    }
    #[inline(always)]
    fn coeffs(&self) -> &[S::Arr<T>; 6] {
        &self.c
    }
}

