impl<T: gx::Real> Translator<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (8 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Translator<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = -t6;
        let t10 = -t7;
        let t11 = -t8;
        Translator::from_coeffs([t5, t9, t10, t11])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Translator::from_coeffs([t0, t1, t2, t3]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Translator::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Translator<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = t0 - T::from_i64(3);
        let t2 = x[0] * t0;
        let t3 = x[1] * t1;
        let t4 = x[2] * t1;
        let t5 = x[3] * t1;
        let t7 = x[0] * T::from_ratio(3, 2);
        let t8 = (-t2).mul_add(T::from_ratio(1, 2), t7);
        let t9 = t3 * T::from_ratio(1, 2);
        let t10 = -t9;
        let t11 = t4 * T::from_ratio(1, 2);
        let t12 = -t11;
        let t13 = t5 * T::from_ratio(1, 2);
        let t14 = -t13;
        Translator::from_coeffs([t8, t10, t12, t14])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Log<Line<(), T>> for gx::Unit<Translator<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Line<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let [h0, h1] = gx::study::log_coeffs(-1, (x[0], T::from_i64(0)), (T::from_i64(0), T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Line::from_coeffs([T::from_i64(0), T::from_i64(0), T::from_i64(0), t0, t1, t2])
        })
    }
}

