impl<T: gx::Real> Flector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[7] * x[7];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (55 mul, 28 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Flector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[7] * x[7];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t0.mul_add(t1, t6);
        let t18 = t0.mul_add(t3, t17);
        let t19 = t1.mul_add(t2, t10);
        let t20 = t2.mul_add(t3, t19);
        let t21 = t18 + t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 + t26;
        let t30 = t27 + t28;
        let t31 = t29 + t30;
        let t32 = t25 - t26;
        let t33 = x[0] * x[4];
        let t35 = x[1] * x[5];
        let t36 = t24 * t35;
        let t37 = t24.mul_add(t33, t36);
        let t38 = t27 - t28;
        let t39 = x[2] * x[6];
        let t41 = x[3] * x[7];
        let t42 = t24 * t41;
        let t43 = t24.mul_add(t39, t42);
        let t44 = x[0] * x[1];
        let t45 = x[2] * x[7];
        let t46 = t24 * t44;
        let t47 = t24 * t45;
        let t48 = x[0] * t31;
        let t49 = x[1] * t31;
        let t50 = x[2] * t31;
        let t53 = x[3] * t38;
        let t54 = x[7] * t37;
        let t56 = x[0] * t43;
        let t57 = x[4] * t32;
        let t60 = x[1] * t43;
        let t62 = x[5] * t30;
        let t64 = x[2] * t37;
        let t66 = x[6] * t38;
        let t67 = x[7] * t31;
        let t68 = x[3].mul_add(t29, t53);
        let t69 = x[6].mul_add(t47, t54);
        let t71 = (-t69).mul_add(T::from_i64(2), t68);
        let t72 = (-x[4]).mul_add(t30, t57);
        let t73 = x[5].mul_add(t46, t56);
        let t75 = t73.mul_add(T::from_i64(2), t72);
        let t76 = x[5].mul_add(t32, t62);
        let t77 = x[4].mul_add(t46, t60);
        let t79 = t77.mul_add(T::from_i64(2), -t76);
        let t80 = (-x[6]).mul_add(t29, t66);
        let t81 = x[3].mul_add(t47, t64);
        let t83 = t81.mul_add(T::from_i64(2), t80);
        let t84 = -t67;
        Flector::from_coeffs([t48, t49, t50, t71, t75, t79, t83, t84])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[7] * x[7];
        let p5 = x[1] * x[5];
        let p7 = x[3] * x[7];
        let p8 = x[0].mul_add(x[0], p1);
        let p9 = x[2].mul_add(x[2], p3);
        let p10 = p8 + p9;
        let p11 = x[0].mul_add(x[4], p5);
        let p12 = x[2].mul_add(x[6], p7);
        let p13 = p11 + p12;
        let p14 = p13 * T::from_i64(2);
        let p15 = -p14;
        let [s0, s1] = gx::study::rsqrt_nil(p10, p15);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t6 = x[4] * s0;
        let t8 = x[5] * s0;
        let t10 = x[6] * s0;
        let t11 = x[7] * s0;
        let t12 = (-x[7]).mul_add(s1, t3);
        let t13 = (-x[0]).mul_add(s1, t6);
        let t14 = (-x[1]).mul_add(s1, t8);
        let t15 = (-x[2]).mul_add(s1, t10);
        gx::Unit::new_unchecked(Flector::from_coeffs([t0, t1, t2, t12, t13, t14, t15, t11]))
    }

}

impl<T: gx::Coef> gx::NewtonStep for Flector<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[7] * x[7];
        let t4 = t0 + t1;
        let t5 = t2 + t3;
        let t6 = t4 + t5;
        let t7 = t4 - T::from_i64(3);
        let t8 = t5 - T::from_i64(3);
        let t9 = t0 - t1;
        let t11 = x[1] * x[5];
        let t12 = x[0].mul_add(x[4], t11);
        let t13 = t2 - t3;
        let t15 = x[3] * x[7];
        let t16 = x[2].mul_add(x[6], t15);
        let t18 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t19 = x[0] * x[1];
        let t20 = x[2] * x[7];
        let t21 = x[0] * t18;
        let t22 = x[1] * t18;
        let t23 = x[2] * t18;
        let t26 = x[3] * t13;
        let t27 = x[7] * t12;
        let t29 = x[0] * t16;
        let t31 = x[4] * t9;
        let t33 = x[1] * t16;
        let t35 = x[5] * t9;
        let t37 = x[2] * t12;
        let t39 = x[6] * t13;
        let t40 = x[7] * t18;
        let t41 = t21 * T::from_ratio(3, 2);
        let t42 = t22 * T::from_ratio(3, 2);
        let t43 = t23 * T::from_ratio(3, 2);
        let t44 = x[6].mul_add(t20, t27);
        let t45 = x[3].mul_add(t7, t26);
        let t47 = (-t45).mul_add(T::from_ratio(1, 2), t44);
        let t48 = x[5].mul_add(t19, t29);
        let t49 = (-x[4]).mul_add(t8, t31);
        let t51 = t49.mul_add(T::from_ratio(1, 2), t48);
        let t52 = x[4].mul_add(t19, t33);
        let t53 = x[5].mul_add(t8, t35);
        let t55 = (-t53).mul_add(T::from_ratio(1, 2), t52);
        let t56 = x[3].mul_add(t20, t37);
        let t57 = (-x[6]).mul_add(t7, t39);
        let t59 = t57.mul_add(T::from_ratio(1, 2), t56);
        let t60 = t40 * T::from_ratio(3, 2);
        Flector::from_coeffs([t41, t42, t43, t47, t51, t55, t59, t60])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

