impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for Plane<(), T> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Scalar<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
        let t1 = v[1] * v[1];
        let t3 = v[0].mul_add(v[0], t1);
        let t4 = v[2].mul_add(v[2], t3);
        let t5 = xv[0] * t4;
            return Scalar { c: gx::slots::from_values::<S, T, 1>([t5]) };
        }
        let m1 = v[1] * v[1];
        let m3 = v[0].mul_add(v[0], m1);
        let m4 = v[2].mul_add(v[2], m3);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Scalar { c: [(x[0].scale(m4)).0] }
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Scalar<S, T>> for Plane<(), T> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Scalar<S, T>) -> Scalar<S, T> {
        gx::Transform::transform(self.reverse(), x)
    }
}

impl<T: gx::Coef> gx::Prepare<Scalar> for Plane<(), T> {
    type Output = gx::Prepared<Plane, Scalar, T, 1>;
    #[inline]
    fn prepare(self) -> gx::Prepared<Plane, Scalar, T, 1> {
        let v = self.c;
        let m1 = v[1] * v[1];
        let m3 = v[0].mul_add(v[0], m1);
        let m4 = v[2].mul_add(v[2], m3);
        gx::Prepared::from_entries([m4])
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for gx::Prepared<Plane, Scalar, T, 1> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Scalar<S, T> {
        let m = self.m;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Scalar { c: [(x[0].scale(m[0])).0] }
    }
}

impl<T: gx::Coef> From<gx::Prepared<Plane, Scalar, T, 1>> for Scalar<(Scalar,), T> {
    /// The dense map of the prepared action.
    #[inline]
    fn from(p: gx::Prepared<Plane, Scalar, T, 1>) -> Self {
        let m = p.m;
        Scalar { c: [[m[0]]] }
    }
}

