impl<S: gx::Slots, T: gx::Coef> gx::Transform<Plane<S, T>> for Plane<(), T> {
    type Output = Plane<S, T>;
    #[inline(always)]
    fn transform(self, x: Plane<S, T>) -> Plane<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = t0 - t1;
        let t3 = t0 + t1;
        let t5 = v[1] * xv[1];
        let t6 = v[0].mul_add(xv[0], t5);
        let t7 = v[2] * v[2];
        let t8 = v[2] * xv[2];
        let t9 = v[0] * v[1];
        let t11 = v[0] * t8;
        let t13 = xv[0] * t2;
        let t15 = v[1] * t8;
        let t17 = xv[1] * t2;
        let t18 = xv[2] * t7;
        let t19 = v[2] * t6;
        let t23 = v[3] * t6;
        let t24 = xv[3] * t3;
        let t25 = (-xv[0]).mul_add(t7, t13);
        let t26 = xv[1].mul_add(t9, t11);
        let t28 = t26.mul_add(T::from_i64(2), t25);
        let t29 = xv[1].mul_add(t7, t17);
        let t30 = xv[0].mul_add(t9, t15);
        let t32 = t30.mul_add(T::from_i64(2), -t29);
        let t33 = (-xv[2]).mul_add(t3, t18);
        let t35 = t19.mul_add(T::from_i64(2), t33);
        let t36 = xv[3].mul_add(t7, t24);
        let t37 = v[3].mul_add(t8, t23);
        let t39 = t37.mul_add(T::from_i64(2), -t36);
            return Plane { c: gx::slots::from_values::<S, T, 4>([t28, t32, t35, t39]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = v[0] * v[1];
        let m4 = v[0] * v[2];
        let m5 = v[1] * v[2];
        let m6 = v[0] * v[3];
        let m7 = v[1] * v[3];
        let m8 = v[2] * v[3];
        let m9 = m0 - m1;
        let m10 = m0 + m1;
        let m11 = m9 - m2;
        let m12 = m3 * T::from_i64(2);
        let m13 = m4 * T::from_i64(2);
        let m14 = m2 + m9;
        let m15 = -m14;
        let m16 = m5 * T::from_i64(2);
        let m17 = m2 - m10;
        let m18 = m6 * T::from_i64(2);
        let m19 = m7 * T::from_i64(2);
        let m20 = m8 * T::from_i64(2);
        let m21 = m2 + m10;
        let m22 = -m21;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Plane { c: [(x[0].scale(m11) + x[1].scale(m12) + x[2].scale(m13)).0, (x[0].scale(m12) + x[1].scale(m15) + x[2].scale(m16)).0, (x[0].scale(m13) + x[1].scale(m16) + x[2].scale(m17)).0, (x[0].scale(m18) + x[1].scale(m19) + x[2].scale(m20) + x[3].scale(m22)).0] }
    }
}

