impl<S: gx::Slots, T: gx::Coef> gx::Transform<Rotor<S, T>> for Plane<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Rotor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[2] * v[2];
        let t3 = v[0] * v[1];
        let t4 = v[0] * v[2];
        let t5 = v[1] * v[2];
        let t6 = v[2] * v[3];
        let t7 = v[1] * v[3];
        let t8 = v[0] * v[3];
        let t9 = t0 - t1;
        let t10 = t0 + t1;
        let t11 = t2 + t10;
        let t12 = t9 - t2;
        let t13 = t2 + t9;
        let t14 = t10 - t2;
        let t15 = xv[0] * t11;
        let t18 = xv[3] * t4;
        let t21 = xv[3] * t5;
        let t23 = xv[2] * t5;
        let t26 = xv[3] * t7;
        let t27 = xv[1] * t6;
        let t30 = xv[2] * t8;
        let t31 = xv[2].mul_add(t3, t18);
        let t32 = t31 * T::from_i64(2);
        let t33 = xv[1].mul_add(t12, t32);
        let t34 = xv[1].mul_add(t3, t21);
        let t35 = t34 * T::from_i64(2);
        let t36 = (-xv[2]).mul_add(t13, t35);
        let t37 = xv[1].mul_add(t4, t23);
        let t38 = t37 * T::from_i64(2);
        let t39 = (-xv[3]).mul_add(t14, t38);
        let t40 = (-xv[2]).mul_add(t6, t26);
        let t41 = t40 * T::from_i64(2);
        let t42 = (-xv[3]).mul_add(t8, t27);
        let t43 = t42 * T::from_i64(2);
        let t44 = (-xv[1]).mul_add(t7, t30);
        let t45 = t44 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 8>([t15, t33, t36, t39, t41, t43, t45, T::from_i64(0)]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = v[0] * v[1];
        let m4 = v[0] * v[2];
        let m5 = v[0] * v[3];
        let m6 = v[1] * v[2];
        let m7 = v[1] * v[3];
        let m8 = v[2] * v[3];
        let m9 = m0 - m1;
        let m10 = m0 + m1;
        let m11 = m2 + m10;
        let m12 = m9 - m2;
        let m13 = m3 * T::from_i64(2);
        let m14 = m4 * T::from_i64(2);
        let m15 = m2 + m9;
        let m16 = -m15;
        let m17 = m6 * T::from_i64(2);
        let m18 = m2 - m10;
        let m19 = m8 * T::from_i64(2);
        let m20 = -m19;
        let m21 = m7 * T::from_i64(2);
        let m22 = m5 * T::from_i64(2);
        let m23 = -m22;
        let m24 = -m21;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m11)).0, (x[1].scale(m12) + x[2].scale(m13) + x[3].scale(m14)).0, (x[1].scale(m13) + x[2].scale(m16) + x[3].scale(m17)).0, (x[1].scale(m14) + x[2].scale(m17) + x[3].scale(m18)).0, (x[2].scale(m20) + x[3].scale(m21)).0, (x[1].scale(m19) + x[3].scale(m23)).0, (x[1].scale(m24) + x[2].scale(m22)).0, S::from_flat(&mut |_| T::zero(), 0)] }
    }
}

