        let m3 = v[0] * v[1];
        let m4 = v[0] * v[2];
        let m5 = v[1] * v[2];
        let m8 = v[1] * v[3];
        let m10 = v[2] * v[3];
        let m11 = v[2] * v[4];
        let m12 = v[0] * v[3];
        let m13 = v[1] * v[4];
        let m14 = v[2] * v[5];
