        let m21 = m5 * T::from_i64(2);
        let m22 = (-v[0]).mul_add(v[5], m9);
        let m23 = m22 * T::from_i64(2);
        let m24 = m2 - m13;
        let m25 = (-v[1]).mul_add(v[3], m10);
        let m26 = m25 * T::from_i64(2);
        let m27 = m2 + m13;
        gx::Prepared::from_entries([m14, m15, m16, m18, m20, m21, m23, m24, m26, m27])
