        let m1 = v[0] * v[3];
        let m2 = v[1] * v[3];
        let m3 = v[2] * v[3];
        let m4 = m1 * T::from_i64(2);
        let m5 = -m4;
        let m6 = m2 * T::from_i64(2);
        let m7 = -m6;
        let m8 = m3 * T::from_i64(2);
        let m9 = -m8;
        let m10 = -m0;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Plane { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[2].scale(m0)).0, (x[0].scale(m5) + x[1].scale(m7) + x[2].scale(m9) + x[3].scale(m10)).0] }
