impl<S: gx::Slots, T: gx::Coef> gx::Transform<Point<S, T>> for Point<(), T> {
    type Output = Point<S, T>;
    #[inline(always)]
    fn transform(self, x: Point<S, T>) -> Point<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[3] * v[3];
        let t1 = v[3] * xv[3];
        let t2 = v[0] * t1;
        let t4 = v[1] * t1;
        let t6 = v[2] * t1;
        let t8 = xv[3] * t0;
        let t9 = t2 * T::from_i64(2);
        let t10 = (-xv[0]).mul_add(t0, t9);
        let t11 = t4 * T::from_i64(2);
        let t12 = (-xv[1]).mul_add(t0, t11);
        let t13 = t6 * T::from_i64(2);
        let t14 = (-xv[2]).mul_add(t0, t13);
            return Point { c: gx::slots::from_values::<S, T, 4>([t10, t12, t14, t8]) };
        }
        let m0 = v[3] * v[3];
        let m1 = v[0] * v[3];
        let m2 = v[1] * v[3];
        let m3 = v[2] * v[3];
        let m4 = -m0;
        let m5 = m1 * T::from_i64(2);
        let m6 = m2 * T::from_i64(2);
        let m7 = m3 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Point { c: [(x[0].scale(m4) + x[3].scale(m5)).0, (x[1].scale(m4) + x[3].scale(m6)).0, (x[2].scale(m4) + x[3].scale(m7)).0, (x[3].scale(m0)).0] }
    }
}

