impl<S: gx::Slots, T: gx::Coef> gx::Transform<Rotor<S, T>> for Point<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Rotor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[3] * v[3];
        let t1 = v[0] * v[3];
        let t2 = v[1] * v[3];
        let t3 = v[2] * v[3];
        let t4 = xv[0] * t0;
        let t5 = xv[1] * t0;
        let t6 = xv[2] * t0;
        let t7 = xv[3] * t0;
        let t8 = xv[3] * t2;
        let t11 = xv[1] * t3;
        let t12 = xv[2] * t1;
        let t14 = (-xv[2]).mul_add(t3, t8);
        let t15 = t14 * T::from_i64(2);
        let t16 = (-xv[3]).mul_add(t1, t11);
        let t17 = t16 * T::from_i64(2);
        let t18 = (-xv[1]).mul_add(t2, t12);
        let t19 = t18 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 8>([t4, t5, t6, t7, t15, t17, t19, T::from_i64(0)]) };
        }
        let m0 = v[3] * v[3];
        let m1 = v[0] * v[3];
        let m2 = v[1] * v[3];
        let m3 = v[2] * v[3];
        let m4 = m3 * T::from_i64(2);
        let m5 = -m4;
        let m6 = m2 * T::from_i64(2);
        let m7 = m1 * T::from_i64(2);
        let m8 = -m7;
        let m9 = -m6;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[2].scale(m0)).0, (x[3].scale(m0)).0, (x[2].scale(m5) + x[3].scale(m6)).0, (x[1].scale(m4) + x[3].scale(m8)).0, (x[1].scale(m9) + x[2].scale(m7)).0, S::from_flat(&mut |_| T::zero(), 0)] }
    }
}

