        let m3 = v[3] * v[3];
        let m4 = v[0] * v[1];
        let m5 = v[0] * v[2];
        let m6 = v[0] * v[3];
        let m7 = v[1] * v[2];
        let m8 = v[1] * v[3];
        let m9 = v[2] * v[3];
        let m10 = m0 - m1;
