        let m16 = m6 + m7;
        let m17 = m16 * T::from_i64(2);
        let m18 = m8 - m5;
        let m19 = m18 * T::from_i64(2);
        let m20 = m7 - m6;
        let m21 = m20 * T::from_i64(2);
        let m22 = m10 + m12;
        let m23 = m4 + m9;
        let m24 = m23 * T::from_i64(2);
        let m25 = m5 + m8;
        let m26 = m25 * T::from_i64(2);
        let m27 = m9 - m4;
        let m28 = m27 * T::from_i64(2);
        let m29 = m10 - m12;
        let x = x.c.map(gx::SlotArr::<S, T>);
