impl<S: gx::Slots, T: gx::Coef> gx::Transform<Plane<S, T>> for Translator<(), T> {
    type Output = Plane<S, T>;
    #[inline(always)]
    fn transform(self, x: Plane<S, T>) -> Plane<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = xv[0] * t0;
        let t2 = xv[1] * t0;
        let t3 = xv[2] * t0;
        let t5 = v[0] * v[1];
        let t7 = v[0] * v[2];
        let t8 = xv[1] * t7;
        let t9 = v[0] * v[3];
        let t11 = xv[0].mul_add(t5, t8);
        let t12 = xv[2].mul_add(t9, t11);
        let t13 = t12 * T::from_i64(2);
        let t14 = xv[3].mul_add(t0, t13);
            return Plane { c: gx::slots::from_values::<S, T, 4>([t1, t2, t3, t14]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m2 = v[0] * v[2];
        let m3 = v[0] * v[3];
        let m4 = m1 * T::from_i64(2);
        let m5 = m2 * T::from_i64(2);
        let m6 = m3 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Plane { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[2].scale(m0)).0, (x[0].scale(m4) + x[1].scale(m5) + x[2].scale(m6) + x[3].scale(m0)).0] }
    }
}

