        let t2 = v[0] * v[2];
        let t3 = v[0] * v[3];
        let t4 = xv[0] * t0;
        let t5 = xv[1] * t0;
        let t6 = xv[2] * t0;
        let t7 = xv[3] * t0;
        let t9 = xv[2] * t3;
        let t10 = xv[3] * t1;
        let t13 = xv[1] * t2;
        let t14 = (-xv[3]).mul_add(t2, t9);
        let t15 = t14 * T::from_i64(2);
        let t16 = (-xv[1]).mul_add(t3, t10);
        let t17 = t16 * T::from_i64(2);
        let t18 = (-xv[2]).mul_add(t1, t13);
        let t19 = t18 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 8>([t4, t5, t6, t7, t15, t17, t19, T::from_i64(0)]) };
