        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m2 = v[0] * v[2];
        let m3 = v[0] * v[3];
        let m4 = m3 * T::from_i64(2);
        let m5 = m2 * T::from_i64(2);
        let m6 = -m5;
        let m7 = -m4;
        let m8 = m1 * T::from_i64(2);
        let m9 = -m8;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[2].scale(m0)).0, (x[3].scale(m0)).0, (x[2].scale(m4) + x[3].scale(m6)).0, (x[1].scale(m7) + x[3].scale(m8)).0, (x[1].scale(m5) + x[2].scale(m9)).0, S::from_flat(&mut |_| T::zero(), 0)] }
